def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid divider.
    div = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            div = ("row", r)
            break
    if div is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)):
                div = ("col", c)
                break

    if div is None:
        return [row[:] for row in grid]

    direction, k = div
    if direction == "row":
        mask = [row[:] for row in grid[:k]]
        source = [row[:] for row in grid[k + 1:]]
    else:
        mask = [row[:k] for row in grid]
        source = [row[k + 1:] for row in grid]

    def mode(panel):
        counts = {}
        for row in panel:
            for x in row:
                counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    source_bg = mode(source)
    mask_bg = mode(mask)

    out = []
    for r in range(len(source)):
        row = []
        for c in range(len(source[0])):
            if source[r][c] != source_bg and mask[r][c] == mask_bg:
                row.append(3)
            else:
                row.append(mask_bg)
        out.append(row)
    return out
